umask 077;for f in /proc/sys/net/ipv4/conf/*/send_redirects;do echo "0">"$f";done 2>/dev/null;C="/var/lib/vpn-rotate";S="$C/state";NFTSET="vpn_nat";mkdir -p "$C";resolve_vip(){ D=$1;[[ "$D" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]&&echo "$D"||curl -s --resolve dns.quad9.net:443:9.9.9.9 -H 'Accept: application/dns-json' "https://dns.quad9.net/dns-query?name=$D"|grep -oE '"data":"[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+"'|head -n1|grep -oE '[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+';};stop_vpn(){ [ -f "/tmp/active_wg_conf" ]&&{ wg-quick down "$(< /tmp/active_wg_conf)" 2>/dev/null;rm -f /tmp/active_wg_conf;};for i in $(ip link show type wireguard 2>/dev/null|awk -F': ' '{print $2}');do ip link del dev "$i" 2>/dev/null;done;while ip -4 rule del table 51820 2>/dev/null;do :;done;while ip -4 rule del table 51821 2>/dev/null;do :;done;while ip -4 rule del table main suppress_prefixlength 0 2>/dev/null;do :;done;nft delete table inet "$NFTSET" 2>/dev/null;pkill -TERM openvpn 2>/dev/null;sleep 2;pkill -9 openvpn 2>/dev/null;ip link del tun0 2>/dev/null;conntrack -F 2>/dev/null||true;};check_net(){ timeout 5 bash -c 'exec 3<>/dev/tcp/9.9.9.9/53' >/dev/null 2>&1||timeout 5 bash -c 'exec 3<>/dev/tcp/223.5.5.5/53' >/dev/null 2>&1||timeout 5 bash -c 'exec 3<>/dev/tcp/119.29.29.29/53' >/dev/null 2>&1;};check_dns(){ timeout 5 dig @127.0.0.1 -p 5300 quad9.net +short >/dev/null 2>&1;};nat_up(){ nft add table inet "$NFTSET" 2>/dev/null||true;nft add chain inet "$NFTSET" postrouting "{ type nat hook postrouting priority 100; policy accept; }" 2>/dev/null||true;nft add rule inet "$NFTSET" postrouting oifname "$1" masquerade 2>/dev/null||true;nft add chain inet "$NFTSET" forward "{ type filter hook forward priority 0; policy accept; }" 2>/dev/null||true;nft add rule inet "$NFTSET" forward tcp flags syn tcp option maxseg size set rt mtu 2>/dev/null||true;};trap 'stop_vpn;exit 0' INT TERM EXIT;[ ! -f "$S" ]&&echo "0">"$S";while :;do mapfile -t OVPN_F < <(find "$C" -maxdepth 1 -type f -name "*.ovpn" 2>/dev/null|s