rd start failed (exit ${WG_RC})";sleep 10;continue;fi;echo "$T">/tmp/active_wg_conf;nat_up "$WGIF";elif [[ "$cfg" == *.ovpn ]];then A="$C/auth.txt";[ -f "$A" ]&&AUTH="--auth-user-pass $A"||AUTH="";REMOTE=$(grep -m1 '^remote ' "$cfg"|awk '{print $2}');REMOTE_PORT=$(grep -m1 '^remote ' "$cfg"|awk '{print $3}');[ -z "$REMOTE_PORT" ]&&REMOTE_PORT="1194";if [ -z "$REMOTE" ];then echo "No remote found in config";sleep 10;continue;fi;VIP=$(resolve_vip "$REMOTE");if [ -z "$VIP" ];then echo "Cannot resolve $REMOTE";sleep 10;continue;fi;T="/tmp/ovpn.conf";cp "$cfg" "$T";sed -i "/^remote /d" "$T";echo "remote $VIP $REMOTE_PORT">>"$T";CFG_CIPHER=$(grep '^cipher ' "$cfg"|awk '{print $2}');grep -q "^script-security" "$T"||echo "script-security 2">>"$T";sed -i '/^up /d;/^down /d;/^pull-filter /d;/^redirect-/d' "$T";echo "pull-filter ignore redirect-gateway">>"$T";echo "pull-filter ignore redirect-private">>"$T";echo "redirect-gateway def1 bypass-dhcp">>"$T";echo "pull-filter ignore \"dhcp-option DNS\"">>"$T";echo "reneg-sec 0">>"$T";echo "mute-replay-warnings">>"$T";echo "keepalive 10 60">>"$T";echo "tun-mtu 1400">>"$T";echo "mssfix 1350">>"$T";sed -i '/^data-ciphers/d;/^auth-nocache/d' "$T";echo "auth-nocache">>"$T";if [ -n "$CFG_CIPHER" ];then echo "data-ciphers AES-256-GCM:AES-128-GCM:CHACHA20-POLY1305:$CFG_CIPHER">>"$T";else echo "data-ciphers AES-256-GCM:AES-128-GCM:CHACHA20-POLY1305:AES-128-CBC">>"$T";fi;printf '#!/bin/sh\ntc qdisc replace dev "$dev" root cake 2>/dev/null||true\n'>/tmp/ovpn-up.sh;chmod +x /tmp/ovpn-up.sh;nat_up tun0;openvpn --config "$T" $AUTH --verb 2 --log /tmp/ovpn.log --status /tmp/ovpn.status 1 --up /tmp/ovpn-up.sh --daemon vpn-rotate 2>&1;sleep 5;OPID=$(pgrep -f "openvpn.*vpn-rotate");if [ -z "$OPID" ];then echo "OpenVPN failed to start";tail -30 /tmp/ovpn.log 2>/dev/null||echo "No log found";sleep 10;continue;fi;sleep 15;else echo "Unknown config type: $cfg";sleep 10;continue;fi;IF="";for i in {1..60};do if [ "$IS_WG" -eq 1 ];then ip link show "$WGIF" >/dev/null 2>&1&&IF="$WGIF"&&break;else ip link show tun0 >/dev/null 2>&1&&IF="tun0"&&break;fi;sleep 1;done;if [ -z "$IF" ];then echo "Interface never came up after 60s";continue;fi;echo "Interface $IF is up";tc qdisc replace dev "$IF" root cake 2>/dev/null||true;if [ "$IS_WG" -eq 1 ];then echo "Waiting for WireGuard handshake...";HS=0;for h in {1..45};do LAST=$(wg show "$IF" latest-handshakes 2>/dev/null|awk '{print $2}');if [ -n "$LAST" ]&&[ "$LAST" -gt 0 ];then NOW_TS=$(date +%s);AGE=$((NOW_TS-LAST));if [ "$AGE" -lt 300 ];then HS=1;echo "Handshake successful (age: ${AGE}s)";break;fi;fi;sleep 2;done;if [ "$HS" -eq 0 ];then echo "No handshake after 90s";continue;fi;fi;echo "Testing connectivity...";CONN_OK=0;for attempt in {1..20};do if check_net;then CONN_OK=1;echo "Network connectivity OK";[ "$IS_WG" -eq 0 ]&&tc qdisc replace dev "$IF" root cake 2>/dev/null||true;break;fi;sleep 5;done;if [ "$CONN_OK" -eq 0 ];then echo "Network test failed after 100s";continue;fi;sleep 20;DNS_OK=0;for attempt in {1..15};do if check_dns;then DNS_OK=1;echo "DNS resolution OK";break;fi;sleep 3;done;if [ "$DNS_OK" -eq 0 ];then echo "DNS test failed but continuing";fi;systemctl kill --kill-whom=main -s HUP pihole-ftl.service 2>/dev/null||true;echo "[$(date '+%H:%M:%S')] VPN connected successfully via $IF";START=$(date +%s);FAIL_COUNT=0;while :;do sleep 120;NOW=$(date +%s);UPTIME=$((NOW-START));UPTIME_MIN=$((UPTIME/60));nft list table inet "$NFTSET" >/dev/null 2>&1||{ echo "[$UPTIME_MIN min] NAT table missing, restoring";nat_up "$IF";};if ! check_net || ! check_dns;then FAIL_COUNT=$((FAIL_COUNT+1));echo "[$UPTIME_MIN min] Network check failed ($FAIL_COUNT/3)";[ "$FAIL_COUNT" -ge 3 ]&&{ echo "Network dead after 3 checks";break;};sleep 10;continue;else FAIL_COUNT=0;fi;if [ "$IS_WG" -eq 1 ];then LAST=$(wg show "$IF" latest-handshakes 2>/dev/null|awk '{print $2}');if [ -n "$LAST" ];then AGE=$((NOW-LAST));[ "$AGE" -gt 300 ]&&{ echo "[$UPTIME_MIN min] Handshake too old: ${AGE}s";break;};else echo "[$UPTIME_MIN min] Cannot read handshake";break;fi;fi;[ $((UPTIME%1800)) -lt 120 ]&&echo "[$UPTIME_MIN min] Connection stable";done;echo "Connection lost, will rotate";sleep 10;done
